def place(shop, customer_id, *items):
    return shop.orders.handle_create({"customer_id": customer_id,
                                      "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_packing_slip_returns_customer_name_and_order_id(shop):
    oid = place(shop, "c2", ("BOOK", 1)).body["order_id"]
    body = shop.fulfilment.handle_packing_slip(oid).body
    assert body["order_id"] == oid
    assert body["customer_name"] == "Grace"


def test_packing_slip_lines_use_catalogue_names_in_item_order(shop):
    oid = place(shop, "c1", ("PEN", 2), ("BOOK", 1), ("LAMP", 3)).body["order_id"]
    response = shop.fulfilment.handle_packing_slip(oid)
    assert response.status == 200
    assert response.body["lines"] == [
        {"sku": "PEN", "name": "Pen", "quantity": 2},
        {"sku": "BOOK", "name": "Book", "quantity": 1},
        {"sku": "LAMP", "name": "Lamp", "quantity": 3},
    ]


def test_packing_slip_for_unknown_order_is_not_found(shop):
    response = shop.fulfilment.handle_packing_slip("ord-9999")
    assert response.status == 404
    assert response.body == {"error": "order not found"}


def test_packing_slip_for_cancelled_order_is_conflict(shop):
    oid = place(shop, "c1", ("BOOK", 1)).body["order_id"]
    shop.orders.handle_cancel(oid)
    response = shop.fulfilment.handle_packing_slip(oid)
    assert response.status == 409
    assert response.body == {"error": "order ord-0001 is cancelled"}


def test_packing_slip_does_not_change_stock(shop):
    oid = place(shop, "c1", ("LAMP", 2)).body["order_id"]
    shop.fulfilment.handle_packing_slip(oid)
    assert shop.catalog.handle_get("LAMP").body["on_hand"] == 3

